	// Asm evidence: if int32 [+0x3c0] == 0 -> false; obj=[+0x3b8], null -> false; obj->vtbl[0x28] (slot 5)(obj) false -> false;
	// else return byte [+0x570] != 0 || qword [+0x578] != 0.
